    class SquidGameRLGL : RustPlugin
    {
        #region Config
        private PluginConfig _config;

        protected override void LoadDefaultConfig()
        {
            Puts("Creating a default config...");
            _config = PluginConfig.DefaultConfig();
            _config.PluginVersion = Version;
            SaveConfig();
            Puts("Creation of the default config completed!");
        }

        protected override void LoadConfig()
        {
            base.LoadConfig();
            _config = Config.ReadObject<PluginConfig>();
            if (_config.PluginVersion < Version) UpdateConfigValues();
        }

        private void UpdateConfigValues()
        {
            Puts("Config update detected! Updating config values...");
            _config.PluginVersion = Version;
            Puts("Config update completed!");
            SaveConfig();
        }

        protected override void SaveConfig() => Config.WriteObject(_config);

        public class ItemConfig
        {
            [JsonProperty("ShortName")] public string ShortName;
            [JsonProperty("Минимальное кол-во")] public int MinAmount;
            [JsonProperty("Максимальное кол-во")] public int MaxAmount;
            [JsonProperty("Шанс выпадения предмета [0.0-100.0]")] public float Chance;
            [JsonProperty("Это чертеж? [true/false]")] public bool IsBluePrint;
            [JsonProperty("SkinID (0 - default)")] public ulong SkinID;
            [JsonProperty("Название (empty - default)")] public string Name;
        }

        public class LootTableConfig
        {
            [JsonProperty("Минимальное кол-во элементов")] public int Min;
            [JsonProperty("Максимальное кол-во элементов")] public int Max;
            [JsonProperty("Список предметов")] public List<ItemConfig> Items;
        }

