        string GetMessage(string langKey, ulong UID) => ins.lang.GetMessage(langKey, ins, UID.ToString());

        string GetMessage(string langKey, ulong UID, params object[] args) => (args.Length == 0) ? GetMessage(langKey, UID) : string.Format(GetMessage(langKey, UID), args);
        #endregion Lang

        #region Oxide Hooks
        [PluginReference] Plugin NoEscape;

        private static SquidGameRLGL ins;

        void Init()
        {
            ins = this;
            Unsubscribes();
        }

        void OnServerInitialized()
        {
            foreach (ElectricalBranch branch in UnityEngine.Object.FindObjectsOfType<ElectricalBranch>())
            {
                if (branch.branchAmount == 8923)
                {
                    main = branch;
                    break;
                }
            }
            if (main == null)
            {
                if (attempts < 10)
                {
                    attempts++;
                    timer.In(9f, () => OnServerInitialized());
                }
                else
                {
                    PrintError("The prefab location is missing on the map. The plugin cannot be loaded!");
                    Server.Command($"o.unload {Name}");
                }
                return;
            }
            LoadDefaultMessages();
            FindMonuments();
            timer.In(UnityEngine.Random.Range(_config.MinStartTime, _config.MaxStartTime), () =>
            {
                if (controller == null) Start();
                else Puts("This event is active now. To finish this event (rlglstop), then to start the next one");
            });
        }

        void Unload()
        {
            if (controller != null) Finish();
            ins = null;
        }

        object OnPlayerDeath(BasePlayer player, HitInfo info)
        {
            MemberSquidGame member = controller.members.Where(x => x.player == player).FirstOrDefault();
            if (member != null)
            {
                if (controller.StageGame == 2)
                {
                    controller.ToSpectateMember(member);
                    foreach (MemberSquidGame m in controller.members) PrintToChat(m.player, GetMessage("Loser", m.player.userID, _config.Prefix, player.displayName));
                }
                else if (controller.StageGame == 3)
                {
                    controller.RemoveMember(member);
                    controller.members.Remove(member);
                }
                return true;
            }
            return null;
        }

        object OnServerCommand(ConsoleSystem.Arg arg)
        {
            BasePlayer player = arg.Player();
            if (player == null || string.IsNullOrEmpty(arg.cmd?.FullName)) return null;
            MemberSquidGame member = controller.members.Where(x => x.player == player).FirstOrDefault();
            if (member == null) return null;
            if (arg.cmd.Name == "kill")
            {
                PrintToChat(player, GetMessage("NoSuicide", player.userID, _config.Prefix));
                return false;
            }
            if (_config.Commands.Contains(arg.cmd.Name.ToLower()) || _config.Commands.Contains(arg.cmd.FullName.ToLower()))
            {
                PrintToChat(player, GetMessage("NoAccesCommand", player.userID, _config.Prefix));
                return false;
            }
            return null;
        }

        object OnPlayerCommand(BasePlayer player, string command, string[] args)
        {
            if (player == null) return null;
            MemberSquidGame member = controller.members.Where(x => x.player == player).FirstOrDefault();
            if (member == null) return null;
            command = command.Insert(0, "/");
            if (_config.Commands.Contains(command.ToLower()))
            {
                PrintToChat(player, GetMessage("NoAccesCommand", player.userID, _config.Prefix));
                return false;
            }
            return null;
        }
        #endregion Oxide Hooks

        #region Controller
        ElectricalBranch main;
        ControllerSquidGame controller;

        void Start()
        {
            Subscribes();
            controller = main.gameObject.AddComponent<ControllerSquidGame>();
            foreach (BasePlayer target in BasePlayer.activePlayerList) PrintToChat(target, GetMessage("Wait", target.userID, _config.Prefix, (int)_config.TimeToStart));
        }

        void Finish()
        {
            Unsubscribes();
            foreach (BasePlayer target in BasePlayer.activePlayerList) PrintToChat(target, GetMessage("Finish", target.userID, _config.Prefix, string.IsNullOrEmpty(controller.winners) ? "-" : controller.winners));
            if (controller != null) UnityEngine.Object.Destroy(controller);
            NextTick(() => Server.Command($"o.reload {Name}"));
        }

