            void Awake()
            {
                Transform = GetComponent<Transform>();
                SpawnHead();
                AddMove();
                SpawnWalls();
                SpawnAudio();
                SpawnDummy(GetGlobalPosition(Transform, new Vector3(-2.6f, 1.8f, 47f)), GetGlobalRotation(Transform, new Vector3(2.2f, 182.2f, 0f)));
                SpawnDummy(GetGlobalPosition(Transform, new Vector3(2.6f, 1.8f, 47f)), GetGlobalRotation(Transform, new Vector3(4.5f, 181.5f, 0f)));
                time = ins._config.TimeToStart;
                timeMinStage = ins._config.TimeMinStage;
                timeMaxStage = ins._config.TimeMaxStage;
                timeStage = UnityEngine.Random.Range(timeMinStage, timeMaxStage);
                InvokeRepeating(DecrementTime, 1f, 1f);
                InvokeRepeating(UpdateGUI, 0f, 1f);
            }

            void OnDestroy()
            {
                CancelInvoke(DecrementTime);
                CancelInvoke(UpdateGUI);

                ServerMgr.Instance.StopCoroutine(StageGreen());
                ServerMgr.Instance.StopCoroutine(StageRed());

                foreach (MemberSquidGame member in members) RemoveMember(member);

                KillWalls();

                foreach (BasePlayer dummy in dummies) if (IsAlive(dummy)) dummy.Kill();

                CancelInvoke(PlaySound);
                CancelInvoke(StopSound);
                StopSound();
                if (IsAlive(boomBox)) boomBox.Kill();
                foreach (ConnectedSpeaker speaker in speakers) if (IsAlive(speaker)) speaker.Kill();

                ServerMgr.Instance.StopCoroutine(TurnHeadBack());
                ServerMgr.Instance.StopCoroutine(TurnHeadForward());
                if (IsAlive(sensorRight)) sensorRight.Kill();
                if (IsAlive(sensorLeft)) sensorLeft.Kill();
                if (IsAlive(dropBoxUp)) dropBoxUp.Kill();
                if (IsAlive(dropBoxDown)) dropBoxDown.Kill();
                if (IsAlive(battery)) battery.Kill();
                if (IsAlive(bbq)) bbq.Kill();
            }

            public void AddMember(BasePlayer player)
            {
                MemberSquidGame member = new MemberSquidGame 
                { 
                    player = player,
                    teleportPos = Vector3.zero,
                    containerBelt = ins.SaveItems(player.inventory.containerBelt.itemList), 
                    containerWear = ins.SaveItems(player.inventory.containerWear.itemList), 
                    containerMain = ins.SaveItems(player.inventory.containerMain.itemList),
                    lastPos = Vector3.zero,
                    lastRot = Vector3.zero,
                    IsSpectate = false,
                    IsWinner = false
                };
                if (player.IsBuildingAuthed()) member.teleportPos = player.transform.position;
                else if (ins.spawnMonuments.Count > 0) member.teleportPos = ins.spawnMonuments.GetRandom();
                else member.teleportPos = ServerMgr.FindSpawnPoint(player).pos;
                members.Add(member);
                ClearInventory(player);
                player.State.unHostileTimestamp = 0;
                Teleport(player, GetSpawnPosition());
                player.metabolism.Reset();
                player.SetHealth(100f);
                ItemManager.CreateByName("shoes.boots", 1, 2552314771).MoveToContainer(player.inventory.containerWear);
                ItemManager.CreateByName("pants", 1, 834766778).MoveToContainer(player.inventory.containerWear);
                ItemManager.CreateByName("hoodie", 1, 14072).MoveToContainer(player.inventory.containerWear);
                ins.PrintToChat(player, ins.GetMessage("Enter", player.userID, ins._config.Prefix));
            }
            
            public void RemoveMember(MemberSquidGame member)
            {
                CuiHelper.DestroyUi(member.player, "TextMain");
                CuiHelper.DestroyUi(member.player, "IndicatorMain");
                member.player.State.unHostileTimestamp = 0;
                Teleport(member.player, member.teleportPos);
                member.player.metabolism.Reset();
                member.player.SetHealth(100f);
                ClearInventory(member.player);
                foreach (Item item in ins.RestoreItems(member.containerBelt)) item.MoveToContainer(member.player.inventory.containerBelt);
                foreach (Item item in ins.RestoreItems(member.containerWear)) item.MoveToContainer(member.player.inventory.containerWear);
                foreach (Item item in ins.RestoreItems(member.containerMain)) ins.MoveItem(member.player, item);
                if (member.IsWinner) foreach (Item item in GetWinItems()) ins.MoveItem(member.player, item);
                ins.PrintToChat(member.player, ins.GetMessage("Exit", member.player.userID, ins._config.Prefix));
            }

            public void ToSpectateMember(MemberSquidGame member)
            {
                member.player.State.unHostileTimestamp = 0;
                Vector3 localPos = SpectatePositions.GetRandom();
                localPos.x = UnityEngine.Random.Range(localPos.x - 1f, localPos.x + 1f);
                localPos.z = UnityEngine.Random.Range(localPos.z - 1f, localPos.z + 1f);
                Teleport(member.player, GetGlobalPosition(Transform, localPos));
                member.player.metabolism.Reset();
                member.player.SetHealth(100f);
                member.IsSpectate = true;
                ins.PrintToChat(member.player, ins.GetMessage("ToSpectate", member.player.userID, ins._config.Prefix));
            }

            void SpawnWalls()
            {
                for (int i = 0; i < 5; i++)
                {
                    SimpleBuildingBlock wall = GameManager.server.CreateEntity("assets/prefabs/building/wall.external.high.stone/wall.external.high.stone.prefab", GetGlobalPosition(Transform, new Vector3(11.83f - i * 6.11f, 1.639f, -43.221f)), Quaternion.Euler(GetGlobalRotation(Transform, new Vector3(0f, 0f, 0f)))) as SimpleBuildingBlock;
                    wall.enableSaving = false;
                    wall.Spawn();
                    wall.limitNetworking = true;
                    walls.Add(wall);
                }
            }

            void KillWalls() { foreach (SimpleBuildingBlock wall in walls) if (IsAlive(wall)) wall.Kill(); }

            void SpawnDummy(Vector3 pos, Vector3 rot)
            {
                BasePlayer dummy = GameManager.server.CreateEntity("assets/prefabs/player/player.prefab", pos) as BasePlayer;
                dummy.viewAngles = rot;
                dummy.enableSaving = false;
                dummy.Spawn();

                ClearInventory(dummy);

                ItemManager.CreateByName("smg.mp5").MoveToContainer(dummy.inventory.containerBelt);
                dummy.UpdateActiveItem(dummy.inventory.containerBelt.itemList[0].uid);

                ItemManager.CreateByName("shoes.boots", 1, 2090776132).MoveToContainer(dummy.inventory.containerWear);
                ItemManager.CreateByName("pants", 1, 2631440368).MoveToContainer(dummy.inventory.containerWear);
                ItemManager.CreateByName("hoodie", 1, 2631350189).MoveToContainer(dummy.inventory.containerWear);
                ItemManager.CreateByName("burlap.gloves", 1, 2090790324).MoveToContainer(dummy.inventory.containerWear);
                ItemManager.CreateByName("mask.bandana", 1, 2412392358).MoveToContainer(dummy.inventory.containerWear);
                ItemManager.CreateByName("riot.helmet", 1, 2631346403).MoveToContainer(dummy.inventory.containerWear);

                dummies.Add(dummy);
            }

            void SpawnAudio()
            {
                boomBox = GameManager.server.CreateEntity("assets/prefabs/voiceaudio/boombox/boombox.deployed.prefab", GetGlobalPosition(Transform, new Vector3(-0.023f, 4.223f, 49.170f)), Quaternion.Euler(GetGlobalRotation(Transform, new Vector3(0f, 180f, 0f)))) as DeployableBoomBox;
                boomBox.enableSaving = false;
                boomBox.Spawn();
                boomBox.UpdateFromInput(35, 0);
                IOEntity.IOSlot outSlot = boomBox.outputs[0];
                IOEntity outEntity = boomBox;
                foreach (Location location in SpeakerLocations)
                {
                    ConnectedSpeaker speaker = GameManager.server.CreateEntity("assets/prefabs/voiceaudio/hornspeaker/connectedspeaker.deployed.prefab", GetGlobalPosition(Transform, location.Position), Quaternion.Euler(GetGlobalRotation(Transform, location.Rotation))) as ConnectedSpeaker;
                    speaker.enableSaving = false;
                    speaker.Spawn();
                    speakers.Add(speaker);
                    outSlot.connectedTo.Set(speaker);
                    speaker.inputs[0].connectedTo.Set(outEntity);
                    outEntity.MarkDirtyForceUpdateOutputs();
                    speaker.MarkDirtyForceUpdateOutputs();
                    outSlot = speaker.outputs[0];
                    outEntity = speaker;
                }
                SpawnCassette();
                LoadAudio();
                SetSound("start");
                Invoke(PlaySound, 1f);
            }

            void SpawnCassette()
            {
                Item item = ItemManager.CreateByName("cassette");
                cassette = ItemModAssociatedEntity<Cassette>.GetAssociatedEntity(item);
                cassette.MaxCassetteLength = 30f;
                item.MoveToContainer(boomBox.inventory);
                item.MarkDirty();
                boomBox.OnCassetteInserted(cassette);
            }

            void LoadAudio() { foreach (var dic in ins.sounds[ins._config.Language]) audioIDs.Add(dic.Key, FileStorage.server.Store(dic.Value, FileStorage.Type.ogg, cassette.net.ID)); }

            void SetSound(string key)
            {
                cassette.SetAudioId(audioIDs[key], 76561198328868364);
                currentKey = key;
            }

            void PlaySound()
            {
                boomBox.UpdateFromInput(1, 1);
                Invoke(StopSound, ins.timeSounds[ins._config.Language][currentKey]);
            }

            void StopSound()
            {
                boomBox.UpdateFromInput(0, 1);
                if (currentKey == "start")
                {
                    if (time > ins.timeSounds[ins._config.Language]["start"] + 1f) Invoke(PlaySound, 1f);
                    else SetSound("green");
                }
                else if (currentKey == "red") SetSound("green");
                else if (currentKey == "green") SetSound("red");
            }

            void StartGame()
            {
                StageGame = 2;
                time = ins._config.Time;
                KillWalls();
                foreach (BasePlayer target in BasePlayer.activePlayerList) ins.PrintToChat(target, ins.GetMessage("Start", target.userID, ins._config.Prefix, members.Count));
                IsGreen = true;
                UpdateGUI();
                foreach (MemberSquidGame member in members) ins.PrintToChat(member.player, ins.GetMessage("GreenLight", member.player.userID, ins._config.Prefix));
                PlaySound();
                ServerMgr.Instance.StartCoroutine(StageGreen());
            }

            void FinishGame()
            {
                StageGame = 3;
                IsGreen = false;
                IsRed = false;
                time = ins._config.TimeToFinish;
                UpdateGUI();
                foreach (MemberSquidGame member in members.Where(x => !x.IsSpectate && !x.player.IsHostile())) HostilePlayer(member.player);
                InvokeRepeating(DecrementTime, 1f, 1f);
            }

            void DecrementTime()
            {
                time -= 1f;
                if (time < 1f)
                {
                    if (StageGame == 1) StartGame();
                    else if (StageGame == 2) FinishGame();
                    else if (StageGame == 3) ins.Finish();
                    CancelInvoke(DecrementTime);
                }
            }

            IEnumerator StageGreen()
            {
                float elapsedTime = 0f;
                while (elapsedTime < timeStage)
                {
                    foreach (MemberSquidGame member in members.Where(x => !x.IsSpectate))
                    {
                        if (IsWinner(member.player))
                        {
                            winners += $" {member.player.displayName},";
                            member.IsWinner = true;
                            ToSpectateMember(member);
                            ins.PrintToChat(member.player, ins.GetMessage("ToWinner", member.player.userID, ins._config.Prefix));
                            foreach (MemberSquidGame m in members) ins.PrintToChat(m.player, ins.GetMessage("Winner", m.player.userID, ins._config.Prefix, member.player.displayName));
                        }
                    }
                    elapsedTime += 0.1f;
                    yield return CoroutineEx.waitForSeconds(0.1f);
                    time -= 0.1f;
                }
                ChangeTimeStage();
                if (time > 0f && members.Any(x => !x.IsSpectate)) ServerMgr.Instance.StartCoroutine(TurnHeadForward());
                else FinishGame();
            }

            IEnumerator StageRed()
            {
                IsGreen = false;
                IsRed = true;
                UpdateGUI();
                foreach (MemberSquidGame member in members) ins.PrintToChat(member.player, ins.GetMessage("RedLight", member.player.userID, ins._config.Prefix));
                PlaySound();
                foreach (MemberSquidGame member in members.Where(x => !x.IsSpectate))
                {
                    member.lastPos = member.player.transform.position;
                    member.lastRot = member.player.viewAngles;
                }
                float elapsedTime = 0f;
                int amountTickNoKill = 0;
                while (elapsedTime < timeStage || amountTickNoKill < 5)
                {
                    bool IsTickKill = false;
                    foreach (MemberSquidGame member in members.Where(x => !x.IsSpectate && !x.player.IsHostile()))
                    {
                        if (Vector3.Distance(member.player.transform.position, member.lastPos) > ins._config.ePos || 
                            Math.Abs(member.player.viewAngles.x - member.lastRot.x) > ins._config.eRot || Math.Abs(member.player.viewAngles.y - member.lastRot.y) > ins._config.eRot || Math.Abs(member.player.viewAngles.z - member.lastRot.z) > ins._config.eRot)
                        {
                            ins.PrintToChat(member.player, ins.GetMessage("DetectMove", member.player.userID, ins._config.Prefix));
                            IsTickKill = true;
                            HostilePlayer(member.player);
                        }
                    }
                    if (IsTickKill) amountTickNoKill = 0;
                    else amountTickNoKill++;
                    elapsedTime += 0.1f;
                    yield return CoroutineEx.waitForSeconds(0.1f);
                    time -= 0.1f;
                }
                IsGreen = true;
                IsRed = false;
                UpdateGUI();
                foreach (MemberSquidGame member in members) ins.PrintToChat(member.player, ins.GetMessage("GreenLight", member.player.userID, ins._config.Prefix));
                PlaySound();
                ChangeTimeStage();
                if (time > 0f && members.Any(x => !x.IsSpectate)) ServerMgr.Instance.StartCoroutine(TurnHeadBack());
                else FinishGame();
            }

