            {
                sensorRight = GameManager.server.CreateEntity("assets/prefabs/deployable/playerioents/detectors/hbhfsensor/hbhfsensor.deployed.prefab", GetGlobalPosition(Transform, new Vector3(0.304f, 6.904f, 47.715f)), Quaternion.Euler(GetGlobalRotation(Transform, new Vector3(0f, 0f, 0f)))) as HBHFSensor;
