            IEnumerator TurnHeadBack()
            {
                float wait = 0f;
                Dictionary<BaseEntity, List<PointAnimation>> turnAnimations = new Dictionary<BaseEntity, List<PointAnimation>>();
                foreach (Move move in AllMoveTurnHeadBack)
                {
                    wait += move.time;
                    foreach (EntityPos entityPos in move.entities)
                    {
                        if (!turnAnimations.ContainsKey(entityPos.entity)) turnAnimations.Add(entityPos.entity, new List<PointAnimation>());
                        turnAnimations[entityPos.entity].Add(new PointAnimation { time = move.time, pos = GetGlobalPosition(Transform, entityPos.pos), rot = GetGlobalRotation(Transform, entityPos.rot) });
                    }
                }
                foreach (var dic in turnAnimations) animations[dic.Key].AddPath(dic.Value);
                yield return CoroutineEx.waitForSeconds(wait);
                time -= wait;
                ServerMgr.Instance.StartCoroutine(StageGreen());
            }

            IEnumerator TurnHeadForward()
            {
                float wait = 0f;
                Dictionary<BaseEntity, List<PointAnimation>> turnAnimations = new Dictionary<BaseEntity, List<PointAnimation>>();
                foreach (Move move in AllMoveTurnHeadForward)
                {
                    wait += move.time;
                    foreach (EntityPos entityPos in move.entities)
                    {
                        if (!turnAnimations.ContainsKey(entityPos.entity)) turnAnimations.Add(entityPos.entity, new List<PointAnimation>());
                        turnAnimations[entityPos.entity].Add(new PointAnimation { time = move.time, pos = GetGlobalPosition(Transform, entityPos.pos), rot = GetGlobalRotation(Transform, entityPos.rot) });
                    }
                }
                foreach (var dic in turnAnimations) animations[dic.Key].AddPath(dic.Value);
                yield return CoroutineEx.waitForSeconds(wait);
                time -= wait;
                ServerMgr.Instance.StartCoroutine(StageRed());
            }

