            Vector3 GetGlobalPosition(Transform transform, Vector3 localPosition) => transform.TransformPoint(localPosition);

            Vector3 GetGlobalRotation(Transform transform, Vector3 localRotation) => transform.rotation.eulerAngles + localRotation;

            Vector3 GetLocalPosition(Transform transform, Vector3 globalPosition) => transform.InverseTransformPoint(globalPosition);

            bool IsAlive(BaseNetworkable entity) => entity != null && !entity.IsDestroyed;

            void ClearInventory(BasePlayer player)
            {
                Item[] allItems = Enumerable.ToArray(Enumerable.Concat(player.inventory.containerMain?.itemList ?? Enumerable.Empty<Item>(), Enumerable.Concat(player.inventory.containerBelt?.itemList ?? Enumerable.Empty<Item>(), player.inventory.containerWear?.itemList ?? Enumerable.Empty<Item>())));
                for (int i = allItems.Length - 1; i >= 0; i--)
                {
                    Item item = allItems[i];
                    item.RemoveFromContainer();
                    item.Remove();
                }
            }

            void Teleport(BasePlayer player, Vector3 newPosition)
            {
                if (!player.IsValid()) return;
                try
                {
                    player.UpdateActiveItem (new ItemId(0u));
                    player.EnsureDismounted();
                    if (player.HasParent()) player.SetParent(null, true, true);
                    if (player.IsConnected)
                    {
                        player.EndLooting();
                        if (!player.IsSleeping())
                        {
                            player.SetPlayerFlag(BasePlayer.PlayerFlags.Sleeping, true);
                            player.sleepStartTime = Time.time;
                            BasePlayer.sleepingPlayerList.Add(player);
                            player.CancelInvoke("InventoryUpdate");
                            player.CancelInvoke("TeamUpdate");
                        }
                    }
                    player.RemoveFromTriggers();
                    player.Teleport(newPosition);
                    if (player.IsConnected && !Net.sv.visibility.IsInside(player.net.group, newPosition))
                    {
                        player.SetPlayerFlag(BasePlayer.PlayerFlags.ReceivingSnapshot, true);
                        player.ClientRPCPlayer(null, player, "StartLoading");
                        player.SendEntityUpdate();
                        player.UpdateNetworkGroup();
                        player.SendNetworkUpdateImmediate();
                    }
                }
                finally { player.ForceUpdateTriggers(); }
            }

            List<Item> GetWinItems()
            {
                List<Item> result = new List<Item>();
                int countItems = UnityEngine.Random.Range(ins._config.Loot.Min, ins._config.Loot.Max + 1);
                for (;result.Count <= countItems;)
                {
                    foreach (ItemConfig item in ins._config.Loot.Items)
                    {
                        if (UnityEngine.Random.Range(0.0f, 100.0f) <= item.Chance)
                        {
                            int amount = UnityEngine.Random.Range(item.MinAmount, item.MaxAmount + 1);
                            Item newItem = item.IsBluePrint ? ItemManager.CreateByName("blueprintbase") : ItemManager.CreateByName(item.ShortName, amount, item.SkinID);
                            if (item.IsBluePrint) newItem.blueprintTarget = ItemManager.FindItemDefinition(item.ShortName).itemid;
                            if (item.Name != "") newItem.name = item.Name;
                            result.Add(newItem);
                            if (result.Count == countItems) break;
                        }
                    }
                }
                return result;
            }

