                }
            }
        }

        int attempts = 0;

        [HookMethod("InSquidGame")] 
        bool InSquidGame(BasePlayer player)
        {
            if (controller == null || player == null) return false;
            if (controller.members.Any(x => x.player == player)) return true;
            return false;
        }
        #endregion Helpers

        #region Commands
        [ChatCommand("rlglstart")]
        void ChatStartEvent(BasePlayer player)
        {
            if (player.IsAdmin)
            {
                if (controller == null) Start();
                else PrintToChat(player, GetMessage("EventActive", player.userID, _config.Prefix));
            }
        }

        [ChatCommand("rlglstop")]
        void ChatStopEvent(BasePlayer player)
        {
            if (player.IsAdmin)
            {
                if (controller != null) Finish();
                else Server.Command($"o.reload {Name}");
            }
        }

        [ConsoleCommand("rlglstart")]
        void ConsoleStartEvent(ConsoleSystem.Arg arg)
        {
            if (arg.Player() == null)
            {
                if (controller == null) Start();
                else Puts("This event is active now. To finish this event (rlglstop), then to start the next one");
            }
        }

        [ConsoleCommand("rlglstop")]
        void ConsoleStopEvent(ConsoleSystem.Arg arg)
        {
            if (arg.Player() == null)
            {
                if (controller != null) Finish();
                else Server.Command($"o.reload {Name}");
            }
        }

        [ChatCommand("rlglenter")]
        void ChatEnterEvent(BasePlayer player)
        {
            if (controller != null)
            {
                if (controller.StageGame == 1)
                {
                    if (IsRaidBlock(player)) PrintToChat(player, GetMessage("NoEscape", player.userID, _config.Prefix));
                    else controller.AddMember(player);
                }
                else PrintToChat(player, GetMessage("NoWaitStageEvent", player.userID, _config.Prefix));
            }
            else PrintToChat(player, GetMessage("NoActiveEvent", player.userID, _config.Prefix));
        }

        [ChatCommand("rlglexit")]
        void ChatExitEvent(BasePlayer player)
        {
            if (controller != null)
            {
                MemberSquidGame member = controller.members.Where(x => x.player == player).FirstOrDefault();
                if (member != null)
                {
                    controller.RemoveMember(member);
                    controller.members.Remove(member);
                }
            }
            else PrintToChat(player, GetMessage("NoActiveEvent", player.userID, _config.Prefix));
        }
        #endregion Commands

        #region NTeleportation
        object CanTeleport(BasePlayer player, Vector3 to)
        {
            if (controller != null && (controller.members.Any(x => x.player == player) || Vector3.Distance(main.transform.position, to) < 55f)) return GetMessage("NTeleportation", player.userID, _config.Prefix);
            else return null;
        }
        #endregion NTeleportation
    }
